const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-62.2667, -38.7833]); // Ingeniero White port
  const region = point.buffer(10000); // 10 km radius
  const date1 = '2025-01-30';
  const date2 = '2025-03-11';

  // 2. Data Acquisition - Use Sentinel-1 for water detection (SAR, unaffected by clouds)
  function getWaterImage(date) {
    const start = ee.Date(date);
    const end = start.advance(1, 'day');

    // Try Sentinel-1 GRD collection
    const collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(region)
      .filterDate(start, end)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VH'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .sort('system:time_start', false);

    return collection;
  }

  // Process water area for a date
  function getWaterArea(col, dateLabel) {
    const size = col.size().getInfo();
    console.log(`${dateLabel} Images: ${size}`);

    if (size === 0) {
      return null;
    }

    const image = col.first();
    // Water detection using VV and VH thresholds
    const water = image.select('VV').lt(-15).and(image.select('VH').lt(-25));

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 100,
      maxPixels: 1e9,
    });

    const waterCount = stats.get('VV').getInfo();
    const totalPixels = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 100,
      maxPixels: 1e9,
    }).get('VV').getInfo();

    console.log(`${dateLabel} Valid pixels: ${totalPixels}, Water pixels: ${waterCount}`);

    if (totalPixels === 0) {
      return null;
    }

    // Calculate area in km² (pixel area = 0.01 km² at 100m scale)
    const areaKm2 = waterCount * 0.01;
    return {area: areaKm2, count: waterCount, valid: true};
  }

  // 3. Get water areas for both dates
  const col1 = getWaterImage(date1);
  const col2 = getWaterImage(date2);

  const area1 = getWaterArea(col1, 'Jan 30');
  const area2 = getWaterArea(col2, 'Mar 11');

  // 4. Check for data availability
  if (!area1 || !area2) {
    if (!area1 && col1.size().getInfo() === 0) {
      console.log("No Sentinel-1 images for January 30");
      console.log("<answer>C1</answer>");
      return;
    }
    if (!area2 && col2.size().getInfo() === 0) {
      console.log("No Sentinel-1 images for March 11");
      console.log("<answer>C1</answer>");
      return;
    }
    if (!area1 || !area2) {
      console.log("No valid water pixels in one or both dates");
      console.log("<answer>C2</answer>");
      return;
    }
  }

  // 5. Calculate and validate
  const diff = area2.area - area1.area;
  console.log(`Jan 30 water area: ${area1.area.toFixed(2)} km²`);
  console.log(`Mar 11 water area: ${area2.area.toFixed(2)} km²`);
  console.log(`Difference: ${diff.toFixed(2)} km²`);

  // Check for invalid values
  if (area1.area === null || area2.area === null || 
      isNaN(area1.area) || isNaN(area2.area) ||
      area1.area < 0 || area2.area < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Final decision - increase if difference > 0.1 km² (threshold to avoid noise)
  if (diff > 0.1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
